export function daysSinceRoast(roastedOn: string, today: Date): number {
  const roasted = new Date(`${roastedOn}T00:00:00Z`);
  const current = new Date(
    Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()),
  );
  const ms = current.getTime() - roasted.getTime();
  return Math.floor(ms / (1000 * 60 * 60 * 24));
}

export function isFresh(roastedOn: string, today: Date): boolean {
  const days = daysSinceRoast(roastedOn, today);
  return days >= 0 && days <= 14;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { daysSinceRoast, isFresh } from "../src/freshness.js";

test("day 0", () => {
  const today = new Date(Date.UTC(2026, 9, 12));
  assert.equal(daysSinceRoast("2026-10-12", today), 0);
  assert.equal(isFresh("2026-10-12", today), true);
});

test("day 14", () => {
  const today = new Date(Date.UTC(2026, 9, 26));
  assert.equal(daysSinceRoast("2026-10-12", today), 14);
  assert.equal(isFresh("2026-10-12", today), true);
});

test("day 15", () => {
  const today = new Date(Date.UTC(2026, 9, 27));
  assert.equal(daysSinceRoast("2026-10-12", today), 15);
  assert.equal(isFresh("2026-10-12", today), false);
});

